/* 目标、计划与报告：纯浏览器内存演示。只读主文件事实，刷新后恢复样例。 */
const go_periods = {DAY:'日',WEEK:'周',MONTH:'月',QUARTER:'季',YEAR:'年'};
const go_labels = {DRAFT:'草稿',ACTIVE:'进行中',AT_RISK:'有风险',ACHIEVED:'已达成',MISSED:'未达成',CANCELLED:'已取消',CHECKING:'核对中',BLOCKED:'阻止',READY:'待提交',SUBMITTED:'已提交',CONFIRMED:'已确认',RETURNED:'退回'};
const go_reasons = {BLOCKED_DEPENDENCY:'依赖阻塞',SCOPE_CHANGED:'范围变更',UNDERESTIMATED:'估算不足',REPRIORITIZED:'优先级调整',WAITING_CLIENT:'等待甲方',QUALITY_REWORK:'质量返工',RESOURCE:'资源不足',OTHER:'其他'};
const go_carry = {CARRY_TO_NEXT:'带入下期',DROP:'放弃',ESCALATE:'升级'};
const go_style = 'width:100%;padding:9px 12px;border:1px solid var(--border-strong);border-radius:10px;background:var(--card);color:var(--fg);font:inherit';
const go_state = {period:'WEEK',planOwner:'chen',planOffset:0,planReview:false,treePeriod:'ALL',treeProject:'ALL',treeType:'ALL',treeOwner:'ALL',treeStatus:'ALL',view:'rollup',filter:'ALL',review:false,currentReport:null,fold:{}};
const go_goals = [];
const go_plans = {};
const go_reports = {};
function go_esc(v){return String(v==null?'':v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function go_btn(t,action,kind='',disabled=false){return `<button type="button" class="btn ${kind}" onclick="${action}" ${disabled?'disabled':''}>${t}</button>`;}
function go_badge(s,t){return `<span class="badge ${['ACHIEVED','CONFIRMED'].includes(s)?'b-ok':['BLOCKED','MISSED','CANCELLED'].includes(s)?'b-danger':['AT_RISK','RETURNED'].includes(s)?'b-warn':['SUBMITTED','READY'].includes(s)?'b-info':'b-stale'}">${go_esc(t||go_labels[s]||s)}</span>`;}
function go_table(h,rows){return `<div class="table-wrap"><table><thead><tr>${h.map(t=>`<th>${t}</th>`).join('')}</tr></thead><tbody>${rows||`<tr><td colspan="${h.length}"><div class="empty">暂无记录</div></td></tr>`}</tbody></table></div>`;}
function go_select(label,value,options,action,disabled=false){return `<label class="stack small">${label}<select style="${go_style}" onchange="${action}" ${disabled?'disabled':''}>${options.map(([v,t])=>`<option value="${go_esc(v)}" ${v===value?'selected':''}>${go_esc(t)}</option>`).join('')}</select></label>`;}
function go_input(label,value,action,disabled=false){return `<label class="stack small">${label}<textarea rows="2" maxlength="2000" style="${go_style}" oninput="${action}" ${disabled?'disabled':''}>${go_esc(value)}</textarea></label>`;}
function go_modal(title,body,footer){openModal(`<div class="stack" style="padding:24px"><div class="row"><h3 class="grow">${title}</h3>${go_btn('关闭','closeModal()','ghost sm')}</div>${body}<div id="go_error" class="note danger" role="alert" hidden></div><div class="row wrap">${footer}</div></div>`);}
function go_error(t){const e=document.getElementById('go_error');if(e){e.hidden=false;e.textContent=t;}else toast(t,'triangle-alert');}
function go_type(k){return PEOPLE[k].k!=='a'?'HUMAN':(!PEOPLE[k].origin||PEOPLE[k].origin==='human')?'AGENT_HUMAN':'AGENT_AI';}
function go_person(k){return `<span class="row wrap">${who(k)}${OR(k)}</span>`;}
function go_project(id){const p=PROJECTS.find(p=>p.id===id);return p?p.name.replace(/ Billing| Console| Docs/g,''):'团队级';}
function go_goal(id){return go_goals.find(g=>g.id===id);}
function go_kr(id){return go_goals.flatMap(g=>g.krs).find(k=>k.id===id);}
function go_progress(k){return Math.max(0,Math.min(1,(k.current-k.baseline)/(k.target-k.baseline)));}
function go_total(g){return g.krs.reduce((n,k)=>n+go_progress(k)*k.weight,0)/g.krs.reduce((n,k)=>n+k.weight,0);}
function go_children(g){return go_goals.filter(c=>c.parent===g.id);}
function go_covered(k){return go_goals.some(g=>g.parentKR===k.id&&['ACTIVE','AT_RISK','ACHIEVED'].includes(g.status));}
function go_coverage(g){return g.level==='MEMBER'?null:g.krs.reduce((n,k)=>n+(go_covered(k)?k.weight:0),0)/g.krs.reduce((n,k)=>n+k.weight,0);}
function go_bar(p){return `<div class="progress" role="progressbar" aria-label="进度" aria-valuenow="${Math.round(p*100)}" aria-valuemin="0" aria-valuemax="100"><i style="width:${p*100}%"></i></div>`;}
function go_time(g){const start=new Date(g.start+'T00:00:00Z'),end=new Date(g.end+'T00:00:00Z');let total=0,elapsed=0;for(let d=new Date(start);d<=end;d.setUTCDate(d.getUTCDate()+1)){if(d.getUTCDay()===0||d.getUTCDay()===6)continue;total++;if(d.toISOString().slice(0,10)<='2026-10-11')elapsed++;}return total?elapsed/total:0;}
function go_addGoal(id,title,level,owner,project,parent,parentKR,period,status,krs){go_goals.push({id,title,level,owner,project,parent,parentKR,period,status,start:period==='YEAR'?'2026-01-01':'2026-10-01',end:period==='MONTH'?'2026-10-31':'2026-12-31',description:'以可追溯证据推进交付，子目标挂接上级关键结果。',krs:krs.map((k,i)=>({id:id+'-KR'+(i+1),title:k[0],source:k[1],baseline:k[2],current:k[3],target:k[4],metric:k[5]||'',evidence:k[6]||'',weight:k[7]||1,updated:'2026-10-11 09:45'})),history:[['2026-10-01','草稿 → 进行中','负责人类确认目标对齐'],['2026-10-11',go_labels[status],'刷新系统指标与手填值']]});}
go_addGoal('T-2026','让交付可预测、可追溯','TEAM','sam',null,null,null,'YEAR','ACTIVE',[
 ['已接受工作项','AUTO',0,58,100,'已接受工作项数'],['甲方首次验收率','AUTO',0,82,95,'甲方首次验收率'],['跨项目经验沉淀','MANUAL',0,3,8,'','']
]);
go_addGoal('P1-Q4','账单中心：完成导出与结算闭环','PROJECT','morgan','p1','T-2026','T-2026-KR1','QUARTER','ACTIVE',[
 ['已接受工作项','AUTO',0,18,26,'已接受工作项数'],['返工周期中位数（小时）','AUTO',40,30,20,'返工周期中位数'],['财务操作说明覆盖','MANUAL',0,2,4,'','']
]);
go_addGoal('P2-Q4','商户控制台：稳定交付与验收','PROJECT','morgan','p2','T-2026','T-2026-KR2','QUARTER','AT_RISK',[
 ['已接受工作项','AUTO',0,31,40,'已接受工作项数'],['证据覆盖率','AUTO',0,90,100,'证据覆盖率']
]);
['chen','ada','bo','cy','lead','iris','echo','fern','morgan','sam'].forEach((owner,i)=>{
 const p=owner==='fern'?'p2':'p1',par=p==='p2'?'P2-Q4':'P1-Q4',kr=owner==='echo'?3:owner==='ada'?2:1;
 go_addGoal('M-'+owner,({chen:'改善导出体验',ada:'解决税额返工并补齐证据',bo:'推进导出字段与分页',cy:'完成独立评审',lead:'推进目标拆解与调度',iris:'澄清财务权限',echo:'补齐财务操作说明',fern:'补齐控制台回归',morgan:'推进裁决与交付',sam:'复核项目风险'})[owner],'MEMBER',owner,p,par,par+'-KR'+kr,'MONTH',owner==='ada'?'AT_RISK':owner==='cy'?'ACHIEVED':'ACTIVE',[
  ['可追溯成果','AUTO',0,owner==='cy'?4:1,4,'已接受工作项数'],['协作与复盘记录','MANUAL',0,owner==='cy'?2:1,2,'',owner==='ada'?'#/workitem/BIL-139':owner==='echo'?'#/workitem/BIL-144':'']
 ]);
});
function go_contributors(k){const g=go_goals.find(g=>g.krs.includes(k));return [{owner:g.owner,source:'负责人'}].concat(go_goals.filter(c=>c.owner!==g.owner&&c.parentKR===k.id&&['ACTIVE','AT_RISK','ACHIEVED'].includes(c.status)).map(c=>({owner:c.owner,source:'子目标'})));}
function go_canLink(owner,goalId,krId){const g=go_goal(goalId);if(!g||g.status==='CANCELLED')return false;if(krId&&!g.krs.some(k=>k.id===krId))return false;if(g.level==='MEMBER')return g.owner===owner;return (krId?g.krs.filter(k=>k.id===krId):g.krs).some(k=>go_contributors(k).some(c=>c.owner===owner));}
function go_links(owner){return go_goals.filter(g=>go_canLink(owner,g.id,null)).flatMap(g=>g.krs.filter(k=>go_canLink(owner,g.id,k.id)).map(k=>[g.id+'|'+k.id,g.title+' · '+k.title]));}
function go_treeSet(key,value){go_state[key]=value;route();}
function go_treeMatch(g){return (go_state.treePeriod==='ALL'||g.period===go_state.treePeriod)&&(go_state.treeProject==='ALL'||g.project===go_state.treeProject)&&(go_state.treeOwner==='ALL'||g.owner===go_state.treeOwner)&&(go_state.treeStatus==='ALL'||g.status===go_state.treeStatus)&&(go_state.treeType==='ALL'||(g.level==='MEMBER'&&go_type(g.owner)===go_state.treeType));}
function go_treeVisible(g){return go_treeMatch(g)||go_children(g).some(go_treeVisible);}
function go_treeNode(g){if(!go_treeVisible(g))return '';const cov=go_coverage(g),fold=go_state.fold[g.id];return `<div class="stack" style="border-left:2px solid var(--border);padding:12px 0 12px 16px"><div class="row wrap">${go_btn(fold?'展开':'收起',`go_fold('${g.id}')`,'ghost sm')}<a class="grow" href="#/goal/${g.id}"><b>${go_esc(g.title)}</b></a>${go_badge(g.status)}<span class="small muted">${go_periods[g.period]}度 · ${Math.round(go_total(g)*100)}%</span></div><div class="row wrap small">${go_person(g.owner)}<span>${g.start} 至 ${g.end}</span>${cov===null?'<span class="muted">成员目标无需再拆解</span>':`<span class="badge ${cov<1?'b-warn':'b-ok'}">对齐覆盖率 ${Math.round(cov*100)}% · KR 拆解 ${g.krs.filter(go_covered).length}/${g.krs.length}</span>`}</div>${go_bar(go_total(g))}<div class="muted xs">时间进度（工作日）：${Math.round(go_time(g)*100)}%${g.parent&&go_goal(g.parent).status==='CANCELLED'?' · 父目标已取消':''}</div>${fold?'':g.krs.map(k=>`<div class="stack" style="padding:10px;border:1px ${g.level!=='MEMBER'&&!go_covered(k)?'dashed':'solid'} var(--border)"><div class="row wrap"><b class="grow">${go_esc(k.title)}</b><span class="chip">${k.source==='AUTO'?'自动取数':'手填'}</span>${k.source==='MANUAL'&&!k.evidence?'<span class="badge b-warn">待佐证</span>':''}<span class="mono small">${k.current} / ${k.target}</span></div>${go_bar(go_progress(k))}${g.level!=='MEMBER'&&!go_covered(k)?'<span class="small muted">未拆解</span>':''}${go_children(g).filter(c=>c.parentKR===k.id).map(go_treeNode).join('')}</div>`).join('')}</div>`;}
function go_fold(id){go_state.fold[id]=!go_state.fold[id];route();}
function go_goalActions(g){const closed=['ACHIEVED','MISSED','CANCELLED'].includes(g.status),parent=g.parent?go_goal(g.parent):null;return `<div class="row wrap">${g.status==='DRAFT'?go_btn('激活',`go_goalChange('${g.id}','ACTIVE')`,'primary',!g.krs.length||parent&&!['ACTIVE','AT_RISK'].includes(parent.status)):''}${go_btn('关闭目标',`go_goalClose('${g.id}')`,'',closed||g.status==='DRAFT'||g.end>'2026-10-11'&&go_total(g)<1)}${go_btn('取消目标',`go_goalChange('${g.id}','CANCELLED')`,'danger',closed)}</div><p class="muted xs">以负责人类 ${PEOPLE[g.level==='MEMBER'?'morgan':g.owner].n} 身份操作。关闭需周期结束或进度达到 100%，取消理由必填。</p>`;}
function go_goalClose(id){go_modal('关闭目标',go_select('关闭结果','ACHIEVED',[['ACHIEVED','已达成'],['MISSED','未达成']],"document.getElementById('go_close_result').value=this.value")+`<input id="go_close_result" type="hidden" value="ACHIEVED"><label class="stack">关闭理由<textarea id="go_goal_reason" style="${go_style}"></textarea></label>`,go_btn('确认关闭',`go_goalChange('${id}',document.getElementById('go_close_result').value,true)`,'primary'));}
function go_goalChange(id,status,fromModal=false){const g=go_goal(id);if(['ACHIEVED','MISSED','CANCELLED'].includes(g.status))return go_error('已关闭目标不可修改');if(status==='ACTIVE'){const parent=go_goal(g.parent);if(g.status!=='DRAFT'||!g.krs.length||parent&&!['ACTIVE','AT_RISK'].includes(parent.status))return;}
 if(['ACHIEVED','MISSED'].includes(status)&&(g.status==='DRAFT'||g.end>'2026-10-11'&&go_total(g)<1))return go_error('周期尚未结束且进度未达到 100%');if(status==='CANCELLED'&&!fromModal){go_modal('取消目标',`<label class="stack">取消理由（必填）<textarea id="go_goal_reason" style="${go_style}"></textarea></label><div class="note warn">子目标不会级联取消，将保留父目标已取消提示。</div>`,go_btn('确认取消',`go_goalChange('${id}','CANCELLED',true)`,'danger'));return;}
 const reason=fromModal?document.getElementById('go_goal_reason').value.trim():'负责人类确认目标对齐';if(status==='CANCELLED'&&!reason)return go_error('取消理由必填');g.history.push(['刚刚',go_labels[g.status]+' → '+go_labels[status],reason||'负责人类裁决']);g.status=status;if(fromModal)closeModal();route();}
function go_manual(id){const k=go_kr(id),g=go_goals.find(g=>g.krs.includes(k));if(k.source!=='MANUAL'||['ACHIEVED','MISSED','CANCELLED'].includes(g.status))return;go_modal('更新手填 KR',`<label class="stack">当前值<input id="go_manual_value" type="number" step="any" value="${k.current}" style="${go_style}"></label><label class="stack">佐证链接<input id="go_manual_evidence" value="${go_esc(k.evidence)}" style="${go_style}"></label><div class="note info">负责人类可手填；Agent 自行更新其 KR 时必须附佐证。</div>`,go_btn('保存',`go_manualSave('${id}')`,'primary'));}
function go_manualSave(id){const k=go_kr(id),input=document.getElementById('go_manual_value').value,value=Number(input),evidence=document.getElementById('go_manual_evidence').value.trim();if(input===''||!Number.isFinite(value))return go_error('请输入有效数值');if(evidence&&!/^(https?:\/\/|#\/)/.test(evidence))return go_error('佐证须为网页地址或原型内链接');k.current=value;k.evidence=evidence;k.updated='刚刚';Object.values(go_reports).forEach(r=>{if([...r.completed,...r.next].some(i=>i.kr===id)){r.lastCheckVersion=0;if(r.state==='SUBMITTED'){r.stale=true;r.flags.push('需重新核对');}}});closeModal();route();toast('手填 KR 已更新');}
PAGES['goals']=()=>head('目标与报告','目标树',TEAM.name+' · 2026 年目标自上而下拆解；进度由本级 KR 计算。')+card('周期与筛选',`<div class="row wrap">${go_select('周期',go_state.treePeriod,[['ALL','全部周期'],['YEAR','2026 年'],['QUARTER','2026 年第四季'],['MONTH','2026 年 10 月']],"go_treeSet('treePeriod',this.value)")}${go_select('项目',go_state.treeProject,[['ALL','全部项目'],...PROJECTS.map(p=>[p.id,go_project(p.id)])],"go_treeSet('treeProject',this.value)")}${go_select('成员类型',go_state.treeType,[['ALL','全部成员'],['HUMAN','人'],['AGENT_HUMAN','人工创建 Agent'],['AGENT_AI','AI 创建 Agent']],"go_treeSet('treeType',this.value)")}${go_select('负责人',go_state.treeOwner,[['ALL','全部负责人'],...go_goals.filter(g=>g.level==='MEMBER').map(g=>[g.owner,PEOPLE[g.owner].n])],"go_treeSet('treeOwner',this.value)")}${go_select('状态',go_state.treeStatus,[['ALL','全部状态'],...['ACTIVE','AT_RISK','ACHIEVED','DRAFT','MISSED','CANCELLED'].map(s=>[s,go_labels[s]])],"go_treeSet('treeStatus',this.value)")}</div><p class="muted xs">筛选保留匹配目标的上级路径；覆盖率按 KR 权重计算。</p>`)+card('团队年度 → 项目季度 → 成员月度',go_treeNode(go_goal('T-2026'))||'<div class="empty">当前筛选没有匹配目标</div>',{icon:'target'});
PAGES['goal']=(id)=>{const g=go_goal(id);if(!g)return head('目标详情','目标不存在','请返回目标树。',go_btn('返回目标树',"go('goals')"));const cov=go_coverage(g);return head('目标详情',go_esc(g.title),`${{TEAM:'团队',PROJECT:'项目',MEMBER:'成员'}[g.level]} · ${go_periods[g.period]}度 · ${g.start} 至 ${g.end}`,go_badge(g.status)+go_btn('返回目标树',"go('goals')"))+`<div class="grid g12"><div class="c8 stack">${card('目标信息',`<dl class="kv"><dt>负责人</dt><dd>${go_person(g.owner)}</dd><dt>项目</dt><dd>${go_project(g.project)}</dd><dt>目标描述</dt><dd>${g.description}</dd><dt>上级目标 / KR</dt><dd>${g.parent?`<a href="#/goal/${g.parent}">${go_esc(go_goal(g.parent).title)} · ${go_esc(go_kr(g.parentKR).title)}</a>`:'团队根目标'}</dd><dt>时间进度</dt><dd>${Math.round(go_time(g)*100)}%（工作日）</dd><dt>对齐覆盖率</dt><dd>${cov===null?'不适用（成员目标）':Math.round(cov*100)+'%'}</dd></dl>${go_goalActions(g)}`)}${card('关键结果',go_table(['关键结果 / 来源','基线 / 当前 / 目标','指标或佐证','进度 / 更新'],g.krs.map(k=>`<tr><td>${go_esc(k.title)}<div class="row wrap"><span class="chip">${k.source==='AUTO'?'自动取数':'手填'}</span>${k.source==='MANUAL'&&!k.evidence?'<span class="badge b-warn">待佐证</span>':''}</div></td><td class="mono">${k.baseline} → ${k.current} → ${k.target}<div class="muted xs">${k.target<k.baseline?'降低':'提高'} · 权重 ${k.weight}</div></td><td>${k.source==='AUTO'?go_esc(k.metric)+`<div class="muted xs">范围：${go_project(g.project)}${g.level==='MEMBER'?' · '+PEOPLE[g.owner].n:''} · 每 15 分钟刷新</div>`:k.evidence?`<a href="${go_esc(k.evidence)}">查看佐证</a>`:'尚未附佐证'}${k.source==='MANUAL'?go_btn('更新',`go_manual('${k.id}')`,'sm',['ACHIEVED','MISSED','CANCELLED'].includes(g.status)):''}</td><td>${Math.round(go_progress(k)*100)}%${go_bar(go_progress(k))}<span class="muted xs">${k.updated}</span></td></tr>`).join('')),{icon:'list-checks'})}${card('子目标（按上级 KR 分组）',g.krs.map(k=>`<div class="stack"><b>${go_esc(k.title)}</b>${go_children(g).filter(c=>c.parentKR===k.id).map(c=>`<div class="row wrap"><a class="grow" href="#/goal/${c.id}">${go_esc(c.title)}</a>${go_person(c.owner)}${go_badge(c.status)}</div>`).join('')||`<div class="empty">${g.level==='MEMBER'?'成员目标无需下级目标':'未拆解'}</div>`}</div>`).join('<div class="sep"></div>'))}${card('关联计划项与工作项',go_table(['计划项 / 工作项','关联 KR','实时状态'],WI.filter(w=>w.p===g.project&&(g.level!=='MEMBER'||w.who===g.owner)).map(w=>`<tr><td><a href="#/workitem/${w.id}">${w.id} · ${go_esc(w.t)}</a></td><td>${go_esc(g.krs[0].title)}</td><td>${go_workStatus(w)}</td></tr>`).join(''))+`<p><a href="#/plans">查看本期计划</a> · <a href="#/report/${g.level==='MEMBER'?'R-'+g.owner:g.level==='TEAM'?'R-team':'R-'+g.project}">查看本期报告引用</a></p>`)}${card('状态变更历史',g.history.map(h=>`<div class="row wrap small"><span class="mono muted">${h[0]}</span><b>${h[1]}</b><span>${h[2]}</span></div>`).join(''),{icon:'history'})}</div><div class="c4 stack">${card('目标进度',`<div class="row"><div class="ring" style="--p:${Math.round(go_total(g)*100)}"><div>${Math.round(go_total(g)*100)}%</div></div><span>本级 KR 加权进度</span></div><p class="muted small">子目标进度不自动累加到父 KR。手填建议值由负责人确认后写入。</p>`)}${card('贡献者：谁能推进哪个 KR',g.krs.map(k=>`<div class="stack"><b>${go_esc(k.title)}</b>${go_contributors(k).map(c=>`<div class="row wrap">${go_person(c.owner)}<span class="badge b-info">${c.source}</span></div>`).join('')}</div>`).join('<div class="sep"></div>'),{icon:'users'})}</div></div>`;};
function go_workStatus(w){return w.s==='AGENT_CLAIMED_DONE'?go_badge('DRAFT','已声明完成（未验证）'):w.l===2&&w.s!=='ACCEPTED'?go_badge('AT_RISK','已验证待裁决'):S(w.s);}
function go_dates(kind,offset=0){const d=new Date(Date.UTC(2026,9,kind==='DAY'?11:kind==='WEEK'?5:1));if(kind==='DAY')d.setUTCDate(d.getUTCDate()+offset);if(kind==='WEEK')d.setUTCDate(d.getUTCDate()+offset*7);if(kind==='MONTH')d.setUTCMonth(d.getUTCMonth()+offset);if(kind==='QUARTER')d.setUTCMonth(d.getUTCMonth()+offset*3);if(kind==='YEAR'){d.setUTCMonth(0);d.setUTCFullYear(2026+offset);}const end=new Date(d);if(kind==='WEEK')end.setUTCDate(end.getUTCDate()+6);if(kind==='MONTH'){end.setUTCMonth(end.getUTCMonth()+1);end.setUTCDate(0);}if(kind==='QUARTER'){end.setUTCMonth(end.getUTCMonth()+3);end.setUTCDate(0);}if(kind==='YEAR'){end.setUTCFullYear(end.getUTCFullYear()+1);end.setUTCDate(0);}return [d.toISOString().slice(0,10),end.toISOString().slice(0,10)];}
function go_getPlan(){const key=[go_state.planOwner,go_state.period,go_state.planOffset].join('-');if(!go_plans[key]){const owner=go_state.planOwner;const w=WI.find(w=>w.who===owner&&['READY','CLAIMED','IN_PROGRESS','REWORK'].includes(w.s));go_plans[key]={id:key,owner,period:go_state.period,dates:go_dates(go_state.period,go_state.planOffset),state:'DRAFT',confirmer:owner==='chen'?'morgan':'morgan',comment:'',items:[{title:w?w.t:'复核导出操作说明',work:w?w.id:null,category:w?'':'REVIEW',goal:'M-'+owner,kr:'M-'+owner+'-KR1',estimate:owner==='ada'?'预算 $6.80':'2 小时',carried:w&&w.s==='REWORK'?'上期质量返工':'—'},{title:'沉淀本期协作经验',work:null,category:'OTHER',goal:'',kr:'',estimate:'1 小时',carried:'—'}]};}return go_plans[key];}
function go_planIssues(p){const out=[];if(!p.items.length)out.push('至少需要 1 个计划项');p.items.forEach((i,n)=>{if(!go_goal(i.goal)||go_goal(i.goal).status==='CANCELLED')out.push(`第 ${n+1} 项必须关联有效目标（B3）`);else if(!go_canLink(p.owner,i.goal,i.kr))out.push(`第 ${n+1} 项不是可贡献的目标 / KR（B5）`);});return out;}
function go_planMode(k,v){go_state[k]=v;route();}
function go_planLink(n,v){const p=go_getPlan();if(go_state.planReview||p.state==='SUBMITTED')return;const [g,k]=v.split('|');Object.assign(p.items[n],{goal:g,kr:k||''});p.state=p.state==='CONFIRMED'?'SUBMITTED':'DRAFT';route();}
function go_draftNext(){go_state.planOffset++;const p=go_getPlan();p.items=p.items.filter(i=>i.goal);const g=go_goal('M-'+p.owner);g.krs.filter(k=>go_progress(k)<1).forEach(k=>{if(!p.items.some(i=>i.kr===k.id))p.items.push({title:'建议：推进'+k.title,goal:g.id,kr:k.id,work:null,category:'OTHER',estimate:'待估算',carried:'剩余 KR 建议'});});p.state='DRAFT';route();toast('已按结转项、待办工作项与剩余 KR 起草下周期计划');}
function go_planSubmit(){const p=go_getPlan(),issues=go_planIssues(p);if(go_state.planReview||!['DRAFT','RETURNED'].includes(p.state)||issues.length)return go_error(issues.join('；')||'当前状态不能提交');p.state='SUBMITTED';route();toast(PEOPLE[p.owner].n+' 的计划已提交，请确认对齐');}
function go_decision(kind,id,action){const p=kind==='plan'?go_getPlan():go_reports[id];const actor=p.confirmer;if(p.state!=='SUBMITTED'||!actor||PEOPLE[actor].k!=='h'||actor===p.owner)return go_error('只能由非作者的负责人类确认已提交内容');if(action==='RETURN'){go_modal('退回'+(kind==='plan'?'计划':'报告'),`<label class="stack">退回意见（至少 4 字）<textarea id="go_return" style="${go_style}" minlength="4" maxlength="2000"></textarea></label>`,go_btn('确认退回',`go_return('${kind}','${id}')`,'danger'));return;}p.state='CONFIRMED';p.confirmedBy=actor;if(kind==='report')go_syncParents();route();toast('已由 '+PEOPLE[actor].n+' 确认');}
function go_return(kind,id){const comment=document.getElementById('go_return').value.trim();if(comment.length<4)return go_error('退回意见至少 4 字');const p=kind==='plan'?go_getPlan():go_reports[id];if(p.state!=='SUBMITTED')return;p.state='RETURNED';p.comment=comment;if(kind==='report')go_syncParents();closeModal();route();toast('报告或计划被退回：'+comment);}
PAGES['plans']=()=>{const p=go_getPlan(),issues=go_planIssues(p),readonly=go_state.planReview||p.state==='SUBMITTED';return head('目标与报告','我的计划',`${go_periods[p.period]}计划 · ${p.dates.join(' 至 ')} · ${go_state.planOwner==='ada'?'Ada 的负责人类 Morgan 确认；主管 Agent 只能预审':'阿澈的计划由交付负责人 Morgan 确认'}`,go_badge(p.state,p.state==='CONFIRMED'?'上级已确认':null))+`<div class="row wrap">${Object.entries(go_periods).map(([k,t])=>go_btn(t,`go_planMode('period','${k}')`,go_state.period===k?'primary':'')).join('')}${go_btn('上一周期',"go_planMode('planOffset',go_state.planOffset-1)",'ghost')}${go_btn('下一周期',"go_planMode('planOffset',go_state.planOffset+1)",'ghost')}${go_btn('我的计划',"go_planMode('planOwner','chen')",p.owner==='chen'?'primary':'')}${go_btn('Ada 计划视图',"go_planMode('planOwner','ada')",p.owner==='ada'?'primary':'')}${go_btn(go_state.planReview?'返回作者视角':'上级 Morgan 视角',"go_planMode('planReview',!go_state.planReview)",'ghost')}</div><div class="sep"></div>${card('计划项',`<div class="row wrap">${go_person(p.owner)}<span class="muted small">确认人：${PEOPLE[p.confirmer].n} · 系统起草</span></div>${p.comment?`<div class="note warn">退回意见：${go_esc(p.comment)}</div>`:''}${go_table(['类型 / 标题','目标与 KR','工作项状态','估算 / 结转来源'],p.items.map((i,n)=>`<tr><td><span class="badge b-info">${i.work?'工作项':'非交付任务'}</span><p>${go_esc(i.title)}</p>${!i.work?'<span class="muted xs">类别：'+({REVIEW:'评审',OTHER:'其他'}[i.category]||'其他')+'</span>':''}</td><td>${go_select('关联目标 / KR',i.goal+'|'+i.kr,[['|','请选择可贡献目标 / KR'],...go_links(p.owner)],`go_planLink(${n},this.value)`,readonly)}${!i.goal?'<div class="note danger">必须关联目标（B3），不可提交</div>':!go_canLink(p.owner,i.goal,i.kr)?'<div class="note danger">你不是该 KR 的贡献者（B5）</div>':''}</td><td>${i.work?`<a href="#/workitem/${i.work}">${i.work}</a> ${go_workStatus(WI.find(w=>w.id===i.work))}`:'无交付关联'}</td><td>${i.estimate}<div class="muted xs">${i.carried}</div></td></tr>`).join(''))}<div class="row wrap">${go_btn('保存',"toast('计划草稿已保存在内存中')",'',readonly)}${go_btn('起草下周期计划','go_draftNext()','',go_state.planReview)}${go_state.planReview?go_btn('确认',`go_decision('plan','${p.id}','CONFIRM')`,'primary',p.state!=='SUBMITTED')+go_btn('退回（意见必填）',`go_decision('plan','${p.id}','RETURN')`,'danger',p.state!=='SUBMITTED'):go_btn('提交给上级确认','go_planSubmit()','primary',issues.length>0||!['DRAFT','RETURNED'].includes(p.state))}</div>${issues.length?`<div class="note danger" role="alert">${issues.map(go_esc).join('；')}</div>`:''}<p class="muted xs">已确认计划增删项后须重新确认。Agent 不能确认任何计划。</p>`)}${card('未达成 KR 建议',go_goal('M-'+p.owner).krs.filter(k=>go_progress(k)<1).map(k=>`<div class="row wrap"><span class="grow">建议：${go_esc(k.title)} · 尚差 ${Math.abs(k.target-k.current)}</span>${go_btn('加入计划',`go_planAdd('${k.id}')`,'sm',readonly)}</div>`).join(''))}`;};
function go_planAdd(kr){const p=go_getPlan(),k=go_kr(kr);if(go_state.planReview||p.state==='SUBMITTED')return;p.items.push({title:'建议：推进'+k.title,goal:'M-'+p.owner,kr:k.id,work:null,category:'OTHER',estimate:'待估算',carried:'剩余 KR 建议'});p.state=p.state==='CONFIRMED'?'SUBMITTED':'DRAFT';route();}

/* 报告预览改变的是报告内容样例，不更改 WI 的系统事实。 */
function go_makeReport(id,owner,level='MEMBER',project=null,period='WEEK',dates=go_dates(period)){
 const facts=WI.filter(w=>w.s==='ACCEPTED'&&(level==='TEAM'||level==='PROJECT'&&w.p===project||level==='MEMBER'&&w.who===owner));
 const goal=level==='MEMBER'?'M-'+owner:level==='TEAM'?'T-2026':project==='p1'?'P1-Q4':'P2-Q4';
 const completed=facts.map(w=>({key:w.id,title:w.t,kind:'WORK_ITEM',ref:w.id,goal,kr:goal+'-KR1'}));
 if(owner==='morgan'&&(level==='MEMBER'||project==='p1')){completed.push({key:'D-551',title:'完成税额返工裁决',kind:'DECISION',ref:'D-551',goal,kr:goal+'-KR1'},{key:'D-3',title:'发送账单中心交付包',kind:'DELIVERY',ref:'D-3',goal,kr:goal+'-KR1'});}
 const w=WI.find(w=>w.who===owner&&w.s!=='ACCEPTED')||WI.find(w=>w.id==='BIL-145');
 return {id,owner,level,project,period,dates,confirmer:level==='TEAM'?null:level==='PROJECT'||owner==='morgan'||owner==='sam'?'sam':'morgan',state:'DRAFT',due:period==='DAY'?new Date(new Date(dates[1]+'T00:00:00Z').getTime()+86400000).toISOString().slice(0,10)+' 10:00':'2026-10-13 12:00',completed,uncompleted:[{title:w.t,work:w.id,reason:w.s==='REWORK'?'QUALITY_REWORK':w.l===2?'OTHER':'BLOCKED_DEPENDENCY',detail:w.l===2?'已验证，待裁决':w.s==='REWORK'?'金额按行项目舍入规则尚未满足':'等待甲方澄清财务角色范围',carry:'CARRY_TO_NEXT',confirmed:PEOPLE[owner].k==='a'}],retro:{went_well:'保留证据与裁决链，及时同步阻塞。',problems:'权限澄清与返工影响了交付节奏。',root_causes:'需求基线中的金额口径需要更早确认。',improvements:'下期先核对验收标准，再推进实现。'},retroConfirmed:PEOPLE[owner].k==='a',memory:false,next:[{title:'推进剩余关键结果',goal,kr:goal+'-KR1',work:null}],summary:{completed_count:completed.length,uncompleted_count:1,accepted_work_items:facts.length,cost:facts.reduce((n,w)=>n+w.cost,0),note:completed.length?'':'本期没有达到接受门槛的成果，原因见未完成与复盘。'},childIds:[],missing:0,planConfirmed:false,manualEvidence:false,stale:false,version:1,lastCheckVersion:0,issues:[],flags:[],comment:'',sample:'blocking'};
}
go_goals.filter(g=>g.level==='MEMBER').forEach(g=>{go_reports['R-'+g.owner]=go_makeReport('R-'+g.owner,g.owner,'MEMBER',g.project);});
['p1','p2'].forEach(p=>{const id='R-'+p;go_reports[id]=go_makeReport(id,'morgan','PROJECT',p);go_reports[id].childIds=go_goals.filter(g=>g.level==='MEMBER'&&g.project===p).map(g=>'R-'+g.owner);});
go_reports['R-team']=go_makeReport('R-team','sam','TEAM');go_reports['R-team'].childIds=['R-p1','R-p2'];
function go_factValid(r,i){if(i.kind==='WORK_ITEM'){const w=WI.find(w=>w.id===i.ref);return !!w&&w.s==='ACCEPTED'&&(r.level==='TEAM'||r.level==='PROJECT'&&w.p===r.project||r.level==='MEMBER'&&w.who===r.owner);}if(i.kind==='DECISION')return i.ref==='D-551'&&r.owner==='morgan'&&(r.level==='MEMBER'||r.project==='p1');if(i.kind==='DELIVERY')return i.ref==='D-3'&&r.owner==='morgan'&&(r.level==='MEMBER'||r.project==='p1');if(i.kind==='FREE_TASK_EVIDENCE')return !!i.evidence;return false;}
function go_expected(r){const facts=WI.filter(w=>w.s==='ACCEPTED'&&(r.level==='TEAM'||r.level==='PROJECT'&&w.p===r.project||r.level==='MEMBER'&&w.who===r.owner));return {completed:facts.length+(r.owner==='morgan'&&(r.level==='MEMBER'||r.project==='p1')?2:0),accepted:facts.length,cost:facts.reduce((n,w)=>n+w.cost,0)};}
function go_check(r,save=false){const out=[];const add=(code,section,msg,expected,actual)=>out.push({code,section,msg,expected,actual});r.completed.forEach(i=>{if(!go_factValid(r,i))add('B1','completed',i.ref+' 未达到完成口径','工作项已接受 / 作者裁决 / 已发送交付','系统事实不足，不能计为完成');});
 const expected=go_expected(r),count=expected.completed,accepted=expected.accepted,cost=expected.cost;
 const children=r.childIds.map(id=>go_reports[id]).filter(c=>['SUBMITTED','CONFIRMED'].includes(c.state));const unique=new Set(children.flatMap(c=>c.completed.map(i=>i.kind+':'+i.ref)));
 if(r.summary.completed_count!==count||r.summary.accepted_work_items!==accepted||r.summary.uncompleted_count!==r.uncompleted.length||Math.abs(r.summary.cost-cost)>0.00001||r.level!=='MEMBER'&&r.summary.completed_count<unique.size)add('B2','summary','报告数字与事实 / 下级汇总不一致',`完成 ${count} · 未完成 ${r.uncompleted.length} · 已接受 ${accepted} · 成本 ${money(cost)}`,`完成 ${r.summary.completed_count} · 已接受 ${r.summary.accepted_work_items} · 下级去重 ${unique.size}`);
 r.next.forEach((i,n)=>{const g=go_goal(i.goal);if(!g||g.status==='CANCELLED')add('B3','next','下周期计划第 '+(n+1)+' 项未关联有效目标','存在且未取消的目标','未关联 / 已取消');});
 if(!r.next.length||!Object.values(r.retro).every(v=>v.trim())||!r.retroConfirmed||!r.completed.length&&(!r.summary.note||!r.uncompleted.length&&!r.retro.problems.trim())||r.uncompleted.some(i=>!i.reason||i.detail.trim().length<4||!i.carry||!i.confirmed))add('B4','retro','必填章节或人工确认不完整','四章节完整；复盘与未完成原因已确认','AI 草稿或系统预填待确认');
 [...r.completed,...r.next].forEach(i=>{if(i.kr&&!go_canLink(r.owner,i.goal,i.kr))add('B5','next','声称推进的 KR 不在作者贡献登记内','本人的目标 / 可贡献 KR',i.kr);});
 const total=r.childIds.length+r.missing,submitted=children.length;
 if(total&&submitted<total)add('N1','children','下级报告未全部提交',`${total} 份应提交`,`${total-submitted}/${total} 份未提交`);
 if(!r.planConfirmed)add('N2','next','本期或下期计划未经上级确认','上级已确认','未确认');
 const referenced=[...r.next,...r.completed].map(i=>go_kr(i.kr)).filter(Boolean);if(!r.manualEvidence&&referenced.some(k=>k.source==='MANUAL'&&!k.evidence))add('N3','next','引用的手填 KR 最新值无证据','手填值有佐证','待佐证');
 if(r.stale&&['SUBMITTED','CONFIRMED'].includes(r.state))add('N4','completed','提交后系统事实发生变化','提交时事实保持一致','需重新核对');
 if(save){r.issues=out;r.lastCheckVersion=r.version;r.flags=out.filter(i=>i.code[0]==='N').map(i=>({N1:'未核对',N2:'未确认',N3:'待佐证',N4:'需重新核对'})[i.code]);if(!['SUBMITTED','CONFIRMED'].includes(r.state))r.state=out.some(i=>i.code[0]==='B')?'BLOCKED':'READY';}return out;}
function go_sample(id,mode){const old=go_reports[id];if(['SUBMITTED','CONFIRMED'].includes(old.state))return toast('已提交样例请先退回再编辑');const r=go_makeReport(id,old.owner,old.level,old.project,old.period,old.dates);r.childIds=[...old.childIds];r.sample=mode;r.version=old.version+1;
 if(mode==='blocking'){r.completed.push({key:'bad',title:'账单导出支持 CSV 格式',kind:'WORK_ITEM',ref:'BIL-142',goal:'M-ada',kr:'M-ada-KR1'});r.next.push({title:'整理验收经验',goal:'',kr:''});r.next.push({title:'推进他人关键结果',goal:old.owner==='ada'?'M-chen':'M-ada',kr:old.owner==='ada'?'M-chen-KR1':'M-ada-KR1'});r.summary.completed_count+=2;r.retro.root_causes='';}
 else {r.retroConfirmed=true;r.uncompleted.forEach(i=>i.confirmed=true);r.planConfirmed=mode==='pass';r.manualEvidence=mode==='pass';if(mode==='flags'){r.childIds=[];r.missing=5;r.childSubmittedPreview=3;r.next.push({title:'补齐协作复盘记录',goal:'M-'+r.owner,kr:'M-'+r.owner+'-KR2'});}else{r.childIds=[];r.missing=0;}}
 go_reports[id]=r;go_check(r,true);route();}
/* 仅标记样例的 3 份已提交日报也是独立报告，可从下级面板下钻。 */
function go_seedPreviewChildren(r){if(r.sample!=='flags'||!r.childSubmittedPreview)return;for(let i=0;i<3;i++){const id=r.id+'-day-'+i;if(!go_reports[id]){const c=go_makeReport(id,r.owner,r.level,r.project,'DAY',[`2026-10-0${5+i}`,`2026-10-0${5+i}`]);c.state='SUBMITTED';c.retroConfirmed=true;c.uncompleted.forEach(u=>u.confirmed=true);go_reports[id]=c;}r.childIds.push(id);}r.missing=2;r.childSubmittedPreview=0;}
function go_report(id){if(id==='new')id='R-chen';return go_reports[id];}
function go_edit(id,section,key,value,n=0){const r=go_reports[id];if(go_state.review||r.state==='CONFIRMED')return;if(section==='retro'){r.retro[key]=value;r.retroConfirmed=true;}else if(section==='uncompleted'){r.uncompleted[n][key]=value;if(key==='detail')r.uncompleted[n].confirmed=true;}else if(section==='next'){const [g,k]=value.split('|');r.next[n].goal=g;r.next[n].kr=k||'';}else if(section==='summary'){r.summary[key]=Number(value);}r.version++;r.lastCheckVersion=0;r.state='DRAFT';r.stale=false;go_updatePanel(r);}
function go_acceptAI(id){const r=go_reports[id];if(go_state.review||r.state==='CONFIRMED')return;r.retroConfirmed=true;r.uncompleted.forEach(i=>i.confirmed=true);r.version++;r.lastCheckVersion=0;r.state='DRAFT';route();}
function go_runCheck(id){const r=go_reports[id];if(r.state==='CHECKING')return;r.state=['SUBMITTED','CONFIRMED'].includes(r.state)?r.state:'CHECKING';go_check(r,true);route();toast(r.issues.some(i=>i.code[0]==='B')?'报告存在阻断问题，处理后才能提交':'核对已完成');}
function go_jump(section){const e=document.getElementById('go_section_'+section);if(e){e.scrollIntoView({behavior:window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'center'});e.focus({preventScroll:true});e.style.outline='2px solid var(--warn)';setTimeout(()=>e.style.outline='',1800);}}
function go_issuePanel(r){const issues=go_check(r),blocking=issues.filter(i=>i.code[0]==='B'),non=issues.filter(i=>i.code[0]==='N');const codes=[['B1','completed','完成缺少有效事实'],['B2','summary','计数 / 成本与汇总不符'],['B3','next','计划未挂有效目标'],['B4','retro','必填内容 / 人工确认缺失'],['B5','next','KR 不属于作者贡献链'],['N1','children','下级报告未提交'],['N2','next','计划未确认'],['N3','next','手填 KR 待佐证'],['N4','completed','提交后事实发生变化']];return `<div class="stack"><div class="row wrap">${go_btn('立即核对',`go_runCheck('${r.id}')`,'primary')}<span class="muted xs">${r.lastCheckVersion===r.version?'已核对 · 内容版本 '+r.version:'内容已变化，需重新核对'}</span></div><div class="note ${blocking.length?'danger':non.length?'warn':'ok'}" role="status">${blocking.length?`存在 ${blocking.length} 个阻断问题，处理后才能提交`:non.length?'无阻断，可带标记提交':'全部通过，可以提交'}</div><b>阻止项 B1–B5（必须处理）</b>${codes.slice(0,5).map(c=>go_issueRow(c,issues)).join('')}<b>标记项 N1–N4（可提交但会标记）</b>${codes.slice(5).map(c=>go_issueRow(c,issues)).join('')}<p class="muted xs">已验证不等于已接受；N4 仅表示提交后事实变化。待提交内容或事实变化须重新核对。</p></div>`;}
function go_issueRow(c,issues){const found=issues.filter(i=>i.code===c[0]);return `<button type="button" class="inbox-item" style="width:100%;text-align:left;background:transparent;color:inherit;border:1px solid var(--border)" onclick="go_jump('${c[1]}')"><span class="row wrap"><span class="code">${c[0]}</span><b>${c[2]}</b><span class="badge ${found.length?c[0][0]==='B'?'b-danger':'b-warn':'b-ok'}">${found.length?'发现 '+found.length+' 项':'通过'}</span></span>${found.map(i=>`<span class="small" style="display:block">${go_esc(i.msg)}<span class="muted xs" style="display:block">期望：${go_esc(i.expected)}；实际：${go_esc(i.actual)}</span></span>`).join('')}</button>`;}
function go_submitControls(r){const issues=go_check(r),b=issues.filter(i=>i.code[0]==='B'),n=issues.filter(i=>i.code[0]==='N'),n1=issues.find(i=>i.code==='N1');const missing=r.childIds.length+r.missing-r.childIds.filter(id=>['SUBMITTED','CONFIRMED'].includes(go_reports[id].state)).length,total=r.childIds.length+r.missing;const title=n.length?'提交（带标记'+(n1?'：未核对 '+missing+'/'+total:'')+'）':'提交';if(go_state.review)return `<div class="row wrap">${go_btn('确认',`go_decision('report','${r.id}','CONFIRM')`,'primary',r.state!=='SUBMITTED'||!r.confirmer||r.confirmer===r.owner)}${go_btn('退回（意见必填）',`go_decision('report','${r.id}','RETURN')`,'danger',r.state!=='SUBMITTED'||!r.confirmer||r.confirmer===r.owner)}</div><p class="muted small">最终确认仅限负责人类，禁止自确认。团队所有者提交团队报告后由系统最终确认。</p>`;return `<div class="row wrap">${go_btn('保存',`go_saveReport('${r.id}')`,'',r.state==='CONFIRMED')}${go_btn('重新从系统填充',`go_refill('${r.id}')`,'',r.state==='CONFIRMED')}${go_btn(title,`go_submitReport('${r.id}')`,'primary',b.length>0||['SUBMITTED','CONFIRMED','CHECKING'].includes(r.state))}</div>${b.length?`<p class="small" style="color:var(--danger)">存在 ${b.length} 个阻断问题，处理后才能提交</p>`:''}`;}
function go_updatePanel(r){const panel=document.getElementById('go_check_panel'),controls=document.getElementById('go_submit_controls'),state=document.getElementById('go_report_state');if(panel)panel.innerHTML=go_issuePanel(r);if(controls)controls.innerHTML=go_submitControls(r);if(state)state.innerHTML=go_badge(r.state);if(window.lucide)lucide.createIcons();}
function go_saveReport(id){const r=go_reports[id];if(r.state==='CONFIRMED')return;toast('报告草稿已保存在内存中');}
function go_recount(id){const r=go_reports[id];if(go_state.review||r.state==='CONFIRMED')return;const facts=go_expected(r);r.summary.completed_count=facts.completed;r.summary.uncompleted_count=r.uncompleted.length;r.summary.accepted_work_items=facts.accepted;r.summary.cost=facts.cost;r.version++;r.lastCheckVersion=0;r.state='DRAFT';route();}
function go_moveUncompleted(id,key){const r=go_reports[id];if(go_state.review||r.state==='CONFIRMED')return;const item=r.completed.find(i=>i.key===key);if(!item)return;const w=WI.find(w=>w.id===item.ref);r.completed=r.completed.filter(i=>i.key!==key);if(w&&!r.uncompleted.some(i=>i.work===w.id))r.uncompleted.push({title:w.t,work:w.id,reason:w.s==='REWORK'?'QUALITY_REWORK':'OTHER',detail:w.l===2?'已验证，待裁决':'系统事实尚未达到完成口径',carry:'CARRY_TO_NEXT',confirmed:false});go_recount(id);}
function go_refill(id){go_modal('重新从系统填充','<div class="note warn">将替换当前四章节为系统样例，人工编辑将被覆盖。</div>',go_btn('取消','closeModal()')+go_btn('确认重新填充',`closeModal();go_sample('${id}','blocking')`,'primary'));}
function go_submitReport(id,confirmedFlags=false){const r=go_reports[id];if(go_state.review||['SUBMITTED','CONFIRMED'].includes(r.state))return;const issues=go_check(r,true);if(issues.some(i=>i.code[0]==='B')){route();return toast('报告存在阻断问题，处理后才能提交','triangle-alert');}if(issues.some(i=>i.code[0]==='N')&&!confirmedFlags){go_modal('带标记提交报告',`<div class="note warn">${issues.filter(i=>i.code[0]==='N').map(i=>go_esc(i.msg)).join('<br>')}</div><p>这些标记将随汇总向上传播，确认后提交。</p>`,go_btn('取消','closeModal()')+go_btn('确认带标记提交',`closeModal();go_submitReport('${id}',true)`,'primary'));return;}if(r.lastCheckVersion!==r.version||r.stale)return go_error('核对已失效，请重新核对');r.state=r.level==='TEAM'?'CONFIRMED':'SUBMITTED';r.submittedAt='2026-10-11 10:42';if(r.level==='TEAM')r.confirmedBy='SYSTEM:team_top';go_syncParents();route();toast(PEOPLE[r.owner].n+' 提交了本周期报告'+(r.flags.length?'（'+r.flags.join('、')+'）':''));}
function go_syncParents(){['R-p1','R-p2','R-team'].forEach(id=>{const r=go_reports[id];if(['SUBMITTED','CONFIRMED'].includes(r.state)){r.stale=true;if(!r.flags.includes('需重新核对'))r.flags.push('需重新核对');}else r.lastCheckVersion=0;});}
function go_reportMode(v){go_state.review=v;route();}
function go_evidence(r,i){const w=i.kind==='WORK_ITEM'?WI.find(w=>w.id===i.ref):null;const valid=go_factValid(r,i);const url=i.kind==='WORK_ITEM'?'workitem/'+i.ref:i.kind==='DECISION'?'decision/'+i.ref:'delivery/'+i.ref;return `<div class="row wrap"><a class="chip" href="#/${url}">${I(i.kind==='WORK_ITEM'?'file-check':'link')} ${i.kind==='WORK_ITEM'?'工作项':i.kind==='DECISION'?'裁决':'交付'} ${i.ref}</a>${w?go_workStatus(w):go_badge('CONFIRMED',i.kind==='DELIVERY'?'甲方已验收':'裁决已记录')}${!valid?'<span class="badge b-danger">状态不足，不能列为完成（B1）</span>':''}</div>`;}
PAGES['report']=(id)=>{const r=go_report(id);if(!r)return head('报告编辑器','报告不存在','请从报告中心打开有效报告。',go_btn('返回报告中心',"go('reports')"));go_state.currentReport=r.id;go_seedPreviewChildren(r);const readonly=go_state.review||r.state==='CONFIRMED';const total=r.childIds.length+r.missing,submitted=r.childIds.filter(id=>['SUBMITTED','CONFIRMED'].includes(go_reports[id].state)).length,confirmed=r.childIds.filter(id=>go_reports[id].state==='CONFIRMED').length;
 return head('目标与报告','报告编辑器',`${go_periods[r.period]}报 · ${{MEMBER:'成员',PROJECT:'项目',TEAM:'团队'}[r.level]} · ${r.dates.join(' 至 ')} · ${go_project(r.project)}`,`<span id="go_report_state">${go_badge(r.state)}</span>${go_btn('返回报告中心',"go('reports')")}`)+`<div class="row wrap">${go_person(r.owner)}<span class="small">截止：${r.due}（团队时区：亚洲 / 上海）</span><span class="small">确认人：${r.confirmer?PEOPLE[r.confirmer].n:'团队顶层由系统最终确认'}</span>${go_btn(go_state.review?'返回作者视角':'上级视角',`go_reportMode(${!go_state.review})`,'ghost sm')}</div>${r.flags.length?`<div class="row wrap" style="margin-top:12px">${r.flags.map(f=>`<span class="badge b-warn">${f==='未核对'?'未核对 '+(total-submitted)+'/'+total:f}</span>`).join('')}</div>`:''}${r.flags.includes('逾期')?'<div class="note danger">本周期报告已逾期，请尽快提交；作者与上级将收到提醒。</div>':''}${r.comment?`<div class="note warn">退回意见：${go_esc(r.comment)}</div>`:''}<div class="row wrap" style="margin:16px 0"><b>状态预览</b>${[['blocking','有阻止项'],['flags','仅标记'],['pass','全部通过']].map(([k,t])=>`<button type="button" class="chip ${r.sample===k?'on':''}" aria-pressed="${r.sample===k}" onclick="go_sample('${r.id}','${k}')" ${['SUBMITTED','CONFIRMED'].includes(r.state)||go_state.review?'disabled':''}>${t}</button>`).join('')}<span class="muted xs">切换替换当前样例内容；不更改系统工作项。</span></div><div class="grid g12"><div class="c8 stack"><section id="go_section_summary" tabindex="-1">${card('系统事实与汇总',`<div class="row wrap"><span class="kpi">完成 ${r.summary.completed_count}</span><span>未完成 ${r.summary.uncompleted_count}</span><span>已接受工作项 ${r.summary.accepted_work_items}</span><span>成本 ${money(r.summary.cost)}</span>${go_btn('按系统事实重新计算',`go_recount('${r.id}')`,'sm',readonly)}</div>${r.summary.note?`<p class="muted small">${go_esc(r.summary.note)}</p>`:''}<p class="muted xs">按事实去重，不直接相加下级数字；未覆盖日期以系统记录为准。</p>`)}</section><section id="go_section_completed" tabindex="-1">${card('一、本周期完成（必填）',r.completed.map(i=>`<div class="stack" style="padding:12px;border:1px solid ${go_factValid(r,i)?'var(--border)':'var(--danger)'}"><b>${go_esc(i.title)}</b>${go_evidence(r,i)}${!go_factValid(r,i)?go_btn('移入未完成并结转',`go_moveUncompleted('${r.id}','${i.key}')`,'sm',readonly):''}</div>`).join('')||`<div class="empty">本期无已接受成果。${go_esc(r.summary.note)}</div>`,{icon:'check-check'})}</section><section id="go_section_uncompleted" tabindex="-1">${card('二、未完成（原因与结转必填）',r.uncompleted.map((i,n)=>`<div class="stack"><div class="row wrap"><a class="grow" href="#/workitem/${i.work}">${i.work} · ${go_esc(i.title)}</a>${!i.confirmed?'<span class="badge b-warn">系统预填 · 待确认</span>':go_badge('CONFIRMED','原因已确认')}</div>${go_workStatus(WI.find(w=>w.id===i.work))}<div class="row wrap">${go_select('原因类别',i.reason,Object.entries(go_reasons),`go_edit('${r.id}','uncompleted','reason',this.value,${n})`,readonly)}${go_select('结转决定',i.carry,Object.entries(go_carry),`go_edit('${r.id}','uncompleted','carry',this.value,${n})`,readonly)}</div>${go_input('原因说明（至少 4 字）',i.detail,`go_edit('${r.id}','uncompleted','detail',this.value,${n})`,readonly)}</div>`).join('<div class="sep"></div>'),{icon:'circle-pause'})}</section><section id="go_section_retro" tabindex="-1">${card('三、总结复盘（四项必填）',`<div class="note ${r.retroConfirmed?'ok':'warn'}">${r.retroConfirmed?'复盘已编辑或明确确认':PEOPLE[r.owner].k==='h'?'AI 起草，请编辑或逐条确认':'Agent 自写复盘，最终报告仍须负责人类确认'}</div><div class="stack">${[['went_well','做得好'],['problems','问题'],['root_causes','根因'],['improvements','改进']].map(([k,t])=>go_input(t,r.retro[k],`go_edit('${r.id}','retro','${k}',this.value)`,readonly)).join('')}<label class="row small"><input type="checkbox" ${r.memory?'checked':''} ${readonly?'disabled':''} onchange="go_memory('${r.id}',this.checked)">将改进提议为经验记忆（报告确认后回流）</label>${go_btn('确认复盘与系统预填原因',`go_acceptAI('${r.id}')`,'',readonly)}</div>`,{icon:'notebook-pen'})}</section><section id="go_section_next" tabindex="-1">${card('四、下周期计划（必须挂目标）',r.next.map((i,n)=>`<div class="stack" style="padding:12px;border:1px solid ${i.goal?'var(--border)':'var(--danger)'}"><b>${go_esc(i.title)}</b>${go_select('关联目标 / KR',i.goal+'|'+i.kr,[['|','请选择目标 / KR'],...go_links(r.owner)],`go_edit('${r.id}','next','link',this.value,${n});route()`,readonly)}${!i.goal?'<div class="note danger">必须关联目标（B3）</div>':!go_canLink(r.owner,i.goal,i.kr)?'<div class="note danger">你不是该 KR 的贡献者（B5）</div>':''}</div>`).join(''),{icon:'calendar-check'})}</section><section id="go_section_children" tabindex="-1">${card('下级报告与覆盖率',total?`<div class="row wrap"><span>已提交 ${submitted}/${total}</span><span>已确认 ${confirmed}/${total}</span><span class="badge b-warn">未核对 ${total-submitted}/${total}</span></div>${go_bar(submitted/total)}${r.childIds.map(id=>`<p><a href="#/report/${id}">${PEOPLE[go_reports[id].owner].n} · ${go_periods[go_reports[id].period]}报</a> ${go_badge(go_reports[id].state)}</p>`).join('')}${r.missing?`<div class="note warn">尚缺 ${r.missing} 份下级日报，允许带标记提交。</div>`:''}`:'本报告无下级报告。',{icon:'network'})}</section><div id="go_submit_controls">${go_submitControls(r)}</div></div><aside class="c4"><div id="go_check_panel">${card('即时核对',go_issuePanel(r),{icon:'shield-check'})}</div></aside></div>`;};
function go_memory(id,v){const r=go_reports[id];if(go_state.review||r.state==='CONFIRMED')return;r.memory=v;r.version++;r.lastCheckVersion=0;r.state='DRAFT';go_updatePanel(r);}

function go_reportRow(r,indent=0){const total=r.childIds.length+r.missing,submitted=r.childIds.filter(id=>['SUBMITTED','CONFIRMED'].includes(go_reports[id].state)).length,confirmed=r.childIds.filter(id=>go_reports[id].state==='CONFIRMED').length;const flags=[...new Set([...r.flags,...r.childIds.flatMap(id=>go_reports[id].flags.filter(f=>f!=='逾期'))])];return `<tr><td style="padding-left:${16+indent}px"><a href="#/report/${r.id}"><b>${r.level==='TEAM'?TEAM.name:r.level==='PROJECT'?go_project(r.project):PEOPLE[r.owner].n}</b></a>${r.level==='MEMBER'?OR(r.owner):''}</td><td>${r.summary.completed_count} / ${r.summary.uncompleted_count}</td><td>${total?`提交 ${submitted}/${total} · 确认 ${confirmed}/${total}${go_bar(submitted/total)}`:'—'}</td><td>${total>submitted?`<span class="badge b-warn">未核对 ${total-submitted}/${total}</span>`:''}${r.childIds.some(id=>go_reports[id].flags.includes('逾期'))?`<span class="badge b-warn">逾期 ${r.childIds.filter(id=>go_reports[id].flags.includes('逾期')).length}</span>`:''}${flags.filter(f=>f!=='未核对').map(f=>`<span class="badge b-warn">${f}</span>`).join('')}${r.state==='SUBMITTED'?'<span class="badge b-info">未确认</span>':''}</td><td>${go_badge(r.state)}</td></tr>`;}
function go_calendarReport(owner,col){if(col===7)return go_reports['R-'+owner];const id='C-'+owner+'-'+col;if(!go_reports[id]){const r=go_makeReport(id,owner,'MEMBER',go_goal('M-'+owner).project,'DAY',[`2026-10-${String(5+col).padStart(2,'0')}`,`2026-10-${String(5+col).padStart(2,'0')}`]);const state=['CONFIRMED','SUBMITTED','DRAFT','BLOCKED','DRAFT'][(col+go_goals.findIndex(g=>g.owner===owner&&g.level==='MEMBER'))%5];r.state=state;r.sample=state==='BLOCKED'?'blocking':'pass';r.retroConfirmed=state!=='BLOCKED';r.uncompleted.forEach(i=>i.confirmed=state!=='BLOCKED');r.planConfirmed=state==='CONFIRMED';r.flags=state==='DRAFT'&&col<4?['逾期']:state==='SUBMITTED'&&owner==='ada'?['需重新核对']:[];r.stale=r.flags.includes('需重新核对');go_reports[id]=r;}return go_reports[id];}
function go_centerSet(key,v){go_state[key]=v;route();}
PAGES['reports']=()=>{const members=go_goals.filter(g=>g.level==='MEMBER').map(g=>g.owner);members.forEach(owner=>{for(let col=0;col<5;col++)go_calendarReport(owner,col);});const all=Object.values(go_reports),submitted=all.filter(r=>['SUBMITTED','CONFIRMED'].includes(r.state)),onTime=submitted.filter(r=>!r.flags.includes('逾期')),checked=all.filter(r=>r.lastCheckVersion>0),passed=checked.filter(r=>!r.issues.some(i=>i.code[0]==='B')),pending=all.filter(r=>r.state==='SUBMITTED'&&r.confirmer==='morgan');return head('目标与报告','报告中心',TEAM.name+' · 2026-10-05 至 2026-10-11 · 报告自下而上汇总。')+`<div class="grid g12"><div class="c4">${card('报告准时率',`<div class="kpi">${all.length?Math.round(onTime.length/all.length*100):0}%</div><span class="muted small">按时提交 ${onTime.length} / 应提交 ${all.length}</span>`)}</div><div class="c4">${card('核对通过率',`<div class="kpi">${checked.length?Math.round(passed.length/checked.length*100):0}%</div><span class="muted small">通过 ${passed.length} / 已核对 ${checked.length}（含带标记）</span>`)}</div><div class="c4">${card('待你确认',`<div class="kpi">${pending.length}</div><span class="muted small">Morgan 作为负责人类</span>`)}</div><div class="c12"><div class="tabs row wrap">${[['rollup','汇总'],['calendar','日历']].map(([k,t])=>`<button type="button" class="${go_state.view===k?'on':''}" onclick="go_centerSet('view','${k}')">${t}</button>`).join('')}</div>${go_state.view==='rollup'?card('团队 → 项目 → 成员周报',go_table(['报告主体','完成 / 未完成','覆盖率','标记','提交状态'],go_reportRow(go_reports['R-team'])+['p1','p2'].map(p=>go_reportRow(go_reports['R-'+p],20)+go_reports['R-'+p].childIds.filter(id=>go_reports[id].level==='MEMBER').map(id=>go_reportRow(go_reports[id],40)).join('')).join(''))+'<p class="muted xs">覆盖率分别显示已提交 / 应提交、已确认 / 应提交；标记向上传播，逾期仅按数量显示。</p>',{icon:'network'}):card('成员 × 本周日报与周报',`<div class="row wrap">${go_select('成员类型',go_state.filter,[['ALL','全部成员'],['HUMAN','人类'],['AGENT','Agent'],['AGENT_HUMAN','人工创建 Agent'],['AGENT_AI','AI 创建 Agent']],"go_centerSet('filter',this.value)")}<span class="small muted">${go_badge('CONFIRMED')}${go_badge('SUBMITTED')}${go_badge('DRAFT')}${go_badge('BLOCKED')}<span class="badge b-warn">逾期</span></span></div>${go_table(['成员',...['周一 10/05','周二 10/06','周三 10/07','周四 10/08','周五 10/09','周六 10/10','周日 10/11','本周周报']],members.filter(k=>go_state.filter==='ALL'||go_state.filter==='AGENT'&&PEOPLE[k].k==='a'||go_type(k)===go_state.filter).map(owner=>`<tr><td>${go_person(owner)}</td>${Array.from({length:8},(_,col)=>{if(col===5||col===6)return '<td><span class="muted xs">非工作日<br>不生成日报</span></td>';const r=go_calendarReport(owner,col);return `<td><a href="#/report/${r.id}" title="${go_esc(r.flags.join('、')||go_labels[r.state])}" style="display:block;${r.flags.includes('逾期')?'outline:1px solid var(--warn);border-radius:8px;':''}">${go_badge(r.state)}${r.flags.map(f=>`<div class="xs ${f==='逾期'?'muted':''}">${go_esc(f)}</div>`).join('')}</a></td>`;}).join('')}</tr>`).join(''))}<div class="note info">默认工作日为周一至周五。周末保留网格列，不生成日报；人类日报可选，Agent 默认必须日报。</div>`,{icon:'calendar-days'})}</div></div>`;};
/* 日 → 周与成员 → 项目双向链接；周末没有日报对象。 */
go_goals.filter(g=>g.level==='MEMBER').forEach(g=>{const r=go_reports['R-'+g.owner];for(let col=0;col<5;col++){const child=go_calendarReport(g.owner,col);r.childIds.push(child.id);}});
/* 初始化周报：事实一致的报告与待处理报告并存。 */
Object.values(go_reports).filter(r=>r.period==='WEEK').forEach(r=>{go_check(r,true);if(['bo','cy','fern'].includes(r.owner)&&r.level==='MEMBER'){r.retroConfirmed=true;r.uncompleted.forEach(i=>i.confirmed=true);r.planConfirmed=true;go_check(r,true);r.state=r.owner==='bo'?'CONFIRMED':'SUBMITTED';}});
[['goals','目标树','goals'],['goal','目标详情','goals'],['plans','我的计划','plans'],['report','报告编辑器','reports'],['reports','报告中心','reports']].forEach(([key,title,parent])=>{TITLES[key]=title;NAVPARENT[key]=parent;});
